// =============================================================================
// LsqWrapper.sv —— 访存队列（LSQ）的最外层：LoadQueue + StoreQueue + 两者之间的胶水
//
// 对应 Chisel: xiangshan.mem.LsqWrapper（src/main/scala/xiangshan/mem/lsqueue/LSQWrapper.scala）
//
// 在流水线里的位置：MemBlock 里。dispatch 把访存指令一次最多 6 条送进来（enq），每条带一个
// 2 位 needAlloc：bit0 = 要占 LoadQueue 的项，bit1 = 要占 StoreQueue 的项（向量访存可能两个都要）；
// 两个队列各自分配后，把自己的指针（lqIdx / sqIdx）互相交给对方写进 uop。
// 其余端口基本是两个子队列各自对外接口的直通（load 流水 / store 流水 / ROB / sbuffer ...）。
//
// 子模块（golden 同名例化，都已签核）：
//   LoadQueue  loadQueue   —— 本 lane 的装配层（6 个子队列，见 LoadQueue.sv）
//   StoreQueue storeQueue  —— store 队列
//
// 胶水（xs_LsqWrapper_core，全部手写）：
//   §1 入队拆分：needAlloc 的两位分给两个队列；canAccept = 两边都能收；
//   §2 LoadQueueReplay 的 TLB 重放延迟配置：4 个常数 {14, 0, 125, 0}；
//   §3 uncache 总线仲裁：两个队列共用一条 uncache 通道 —— 同时有请求时让 robIdx 更老的先走，
//      发出后进 s_load / s_store 等回应（不接受新请求）；outstanding 模式下的 NC 请求不等回应。
//      回应 / idResp 按总线给的 is2lq 位分发；
//   §4 异常地址：CSR 读 exceptionAddr 时，按上一拍的 isStore 选 StoreQueue 还是 LoadQueue 的；
//   §5 性能事件：LoadQueue 27 个 + StoreQueue 8 个，统一打两拍输出。
//
// ★照抄 golden、看起来冗余的结构：§4 的 RegNext(isStore) 有 5 份（Scala 每个字段各写一次
//   RegNext，firtool 没合并），一份都不少（见 CONVENTIONS「看起来冗余的重复结构」）。
// ★golden 里被消掉、因此本文件也不写的东西：exceptionAddr 的 vstart/vl（父级不读）、StoreQueue 的
//   uncache 请求 cmd 端口（Scala 里恒为 M_XWR，本层按常数补上）、三条 assert（golden 在 SYNTHESIS 下也不生成）。
//
// 复位域：pending_q 异步复位到 s_idle；其余（5 份 isStore 打拍、70 个 perf 打拍）不复位。
//
// 本文件导航：
//   lsqwrapper_pkg       uncache 请求 / 异常地址结构体、M_XWR、仲裁状态常量、robIdx 比较
//   xs_LsqWrapper_core   §1 入队拆分  §2 TLB 重放延迟常数  §3 uncache 总线仲裁  §4 异常地址  §5 性能事件
//   LsqWrapper           golden 同名 wrapper（GENERATED，scripts/gen_lsq.py）：端口表 → 子队列输出线
//                        （lq_ / sq_ + 端口名去掉 io_）→ 结构体拆装 → 胶水核例化 → loadQueue / storeQueue
//                        例化（实例名、端口顺序同 golden）→ 本层输出 assign
// =============================================================================

package lsqwrapper_pkg;

  // uncache 通道的请求（字段顺序同 golden 端口表）
  typedef struct packed {
    logic        robIdx_flag;
    logic [7:0]  robIdx_value;
    logic [4:0]  cmd;
    logic [47:0] addr;
    logic [49:0] vaddr;
    logic [63:0] data;
    logic [7:0]  mask;
    logic [6:0]  id;
    logic        nc;
    logic        memBackTypeMM;
  } uncache_req_t;

  // 给 CSR 的异常地址
  typedef struct packed {
    logic [63:0] vaddr;
    logic        vaNeedExt;
    logic        isHyper;
    logic [63:0] gpaddr;
    logic        isForVSnonLeafPTE;
  } exc_addr_t;

  // StoreQueue 发的 uncache 请求都是写（rocket-chip MemoryOpConstants.M_XWR）
  localparam logic [4:0] M_XWR = 5'h01;

  // uncache 仲裁状态（Scala Enum(3)；值 3 不可达，出现了就原地不动 —— 与 golden 一致）
  localparam logic [1:0] S_IDLE  = 2'd0;
  localparam logic [1:0] S_LOAD  = 2'd1;   // 发出的是 LoadQueue 的请求，等回应
  localparam logic [1:0] S_STORE = 2'd2;   // 发出的是 StoreQueue 的请求，等回应

  // robIdx 环形指针比较：a 比 b 老（Scala RobPtr 的 <）
  function automatic logic rob_older(input logic a_flag, input logic [7:0] a_value,
                                     input logic b_flag, input logic [7:0] b_value);
    return a_flag ^ b_flag ^ (a_value < b_value);
  endfunction

endpackage


module xs_LsqWrapper_core
  import lsqwrapper_pkg::*;
(
  input  logic             clock,
  input  logic             reset,
  // ---- §1 入队拆分 ----
  input  logic [5:0][1:0]  enq_need_alloc,       // [k] = {要占 SQ, 要占 LQ}
  input  logic [5:0]       enq_req_valid,
  output logic [4:0]       lq_enq_need_alloc,    // 子队列只有前 5 个 needAlloc 端口
  output logic [5:0]       lq_enq_req_valid,
  output logic [4:0]       sq_enq_need_alloc,
  output logic [5:0]       sq_enq_req_valid,
  input  logic             lq_can_accept,
  input  logic             sq_can_accept,
  output logic             enq_can_accept,
  // ---- §2 TLB 重放延迟配置 ----
  output logic [3:0][6:0]  tlb_replay_delay_ctrl,
  // ---- §3 uncache 仲裁 ----
  input  logic             uncache_outstanding,  // 总线支持多笔在途（NC 请求不必等回应）
  input  logic             lq_unc_req_valid,
  input  uncache_req_t     lq_unc_req,
  input  logic             sq_unc_req_valid,
  input  uncache_req_t     sq_unc_req,
  input  logic             unc_req_ready,
  output logic             lq_unc_req_ready,
  output logic             sq_unc_req_ready,
  output logic             unc_req_valid,
  output uncache_req_t     unc_req,
  input  logic             unc_resp_valid,
  input  logic             unc_resp_is2lq,
  input  logic             unc_idresp_valid,
  input  logic             unc_idresp_is2lq,
  output logic             lq_unc_resp_valid,
  output logic             sq_unc_resp_valid,
  output logic             lq_unc_idresp_valid,
  output logic             sq_unc_idresp_valid,
  // ---- §4 异常地址 ----
  input  logic             exc_is_store,
  input  exc_addr_t        lq_exc_addr,
  input  exc_addr_t        sq_exc_addr,
  output exc_addr_t        exc_addr,
  // ---- §5 性能事件 ----
  input  logic [26:0][5:0] lq_perf,
  input  logic [7:0][5:0]  sq_perf,
  output logic [34:0][5:0] perf_value
);

  localparam int unsigned N_LQ_PERF = 27;
  localparam int unsigned N_PERF    = 35;

  // ---------------------------------------------------------------------------
  // §1 入队拆分
  //   第 k 条指令：needAlloc[k][0] 置位才进 LoadQueue，[1] 置位才进 StoreQueue；
  //   两个队列的 valid 各自与上对应位。第 6 条（k=5）的 needAlloc 只用于 valid 门控。
  // ---------------------------------------------------------------------------
  for (genvar k = 0; k < 6; k++) begin : g_enq
    assign lq_enq_req_valid[k] = enq_need_alloc[k][0] & enq_req_valid[k];
    assign sq_enq_req_valid[k] = enq_need_alloc[k][1] & enq_req_valid[k];
    if (k < 5) begin : g_need
      assign lq_enq_need_alloc[k] = enq_need_alloc[k][0];
      assign sq_enq_need_alloc[k] = enq_need_alloc[k][1];
    end
  end
  assign enq_can_accept = lq_can_accept & sq_can_accept;

  // ---------------------------------------------------------------------------
  // §2 LoadQueueReplay 的 TLB 重放延迟（Scala 里写死的 VecInit(14, 0, 125, 0)）
  // ---------------------------------------------------------------------------
  assign tlb_replay_delay_ctrl[0] = 7'd14;
  assign tlb_replay_delay_ctrl[1] = 7'd0;
  assign tlb_replay_delay_ctrl[2] = 7'd125;
  assign tlb_replay_delay_ctrl[3] = 7'd0;

  // ---------------------------------------------------------------------------
  // §3 uncache 总线仲裁
  //   选谁：只有一边有请求就选那边；两边都有，选 robIdx 更老的（相等时选 store）。
  //   什么时候能发：只在 s_idle。发出（req.fire）后：
  //     outstanding 模式下的 NC 请求 → 仍留在 s_idle（不等回应，可继续发）；
  //     其余 → 进 s_load / s_store，直到总线回应（resp.valid）回 s_idle。
  //   请求的 bits 不受 s_idle 门控（Scala 里非 idle 时是 DontCare，firtool 取了选择结果）。
  //   回应与 idResp 不看状态，只按总线给的 is2lq 位分给一边。
  // ---------------------------------------------------------------------------
  logic [1:0] pending_q;
  logic       idle;
  logic       select_lq;

  assign idle      = (pending_q == S_IDLE);
  assign select_lq = lq_unc_req_valid & ~sq_unc_req_valid
                   | lq_unc_req_valid & sq_unc_req_valid
                     & rob_older(lq_unc_req.robIdx_flag, lq_unc_req.robIdx_value,
                                 sq_unc_req.robIdx_flag, sq_unc_req.robIdx_value);

  assign unc_req_valid    = idle & (select_lq ? lq_unc_req_valid : sq_unc_req_valid);
  assign unc_req          = select_lq ? lq_unc_req : sq_unc_req;
  assign lq_unc_req_ready = idle & select_lq & unc_req_ready;
  assign sq_unc_req_ready = idle & ~select_lq & unc_req_ready;

  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      pending_q <= S_IDLE;
    end else begin
      case (pending_q)
        S_IDLE: begin
          if (unc_req_ready & unc_req_valid) begin
            if (uncache_outstanding & unc_req.nc) pending_q <= S_IDLE;
            else                                  pending_q <= select_lq ? S_LOAD : S_STORE;
          end
        end
        S_LOAD, S_STORE: begin
          if (unc_resp_valid) pending_q <= S_IDLE;
        end
        default: ;   // 不可达的 3：保持
      endcase
    end
  end

  assign lq_unc_resp_valid   = unc_resp_is2lq & unc_resp_valid;
  assign sq_unc_resp_valid   = ~unc_resp_is2lq & unc_resp_valid;
  assign lq_unc_idresp_valid = unc_idresp_is2lq & unc_idresp_valid;
  assign sq_unc_idresp_valid = ~unc_idresp_is2lq & unc_idresp_valid;

  // ---------------------------------------------------------------------------
  // §4 异常地址
  //   ROB 提交到 LSQ 晚两拍，异常被触发的下一拍 CSR 才来读地址，所以按上一拍的 isStore 选。
  //   golden 每个字段各一份 RegNext(isStore)：sel_store_q[i] 对应 exc_addr_t 的第 i 个字段
  //   （0 vaddr / 1 vaNeedExt / 2 isHyper / 3 gpaddr / 4 isForVSnonLeafPTE）。
  // ---------------------------------------------------------------------------
  logic [4:0] sel_store_q;

  always_ff @(posedge clock) begin
    sel_store_q <= {5{exc_is_store}};
  end

  assign exc_addr.vaddr             = sel_store_q[0] ? sq_exc_addr.vaddr             : lq_exc_addr.vaddr;
  assign exc_addr.vaNeedExt         = sel_store_q[1] ? sq_exc_addr.vaNeedExt         : lq_exc_addr.vaNeedExt;
  assign exc_addr.isHyper           = sel_store_q[2] ? sq_exc_addr.isHyper           : lq_exc_addr.isHyper;
  assign exc_addr.gpaddr            = sel_store_q[3] ? sq_exc_addr.gpaddr            : lq_exc_addr.gpaddr;
  assign exc_addr.isForVSnonLeafPTE = sel_store_q[4] ? sq_exc_addr.isForVSnonLeafPTE : lq_exc_addr.isForVSnonLeafPTE;

  // ---------------------------------------------------------------------------
  // §5 性能事件：0..26 = LoadQueue 的 27 个，27..34 = StoreQueue 的 8 个；各打两拍（不复位）。
  // ---------------------------------------------------------------------------
  logic [5:0] perf_d1 [N_PERF];
  logic [5:0] perf_d2 [N_PERF];

  always_ff @(posedge clock) begin
    for (int k = 0; k < N_LQ_PERF; k++) begin
      perf_d1[k] <= lq_perf[k];
    end
    for (int k = N_LQ_PERF; k < N_PERF; k++) begin
      perf_d1[k] <= sq_perf[k - N_LQ_PERF];
    end
    for (int k = 0; k < N_PERF; k++) begin
      perf_d2[k] <= perf_d1[k];
    end
  end

  for (genvar k = 0; k < N_PERF; k++) begin : g_perf_out
    assign perf_value[k] = perf_d2[k];
  end

endmodule


